import { describe, expect, it } from 'vitest';
import { Add, AppliedUndef, E, Float, I, Le, Lt, Mul, Pow, Relational, Sym, add, constantRenumber, constantsimp, fn, integral, log, mul, nsolve, piecewise, pow, rational, solve, symbols } from '../src';
import { at, sympyStr } from './sympy-str';

describe("doctests of sympy.solvers", () => {
  it("solve(((x + 1)**5).expand(), x)", () => {
    const x = new Sym('x');
    expect(sympyStr([at(solve(add(1, pow(x, 5), mul(5, x), mul(5, pow(x, 4)), mul(10, pow(x, 2)), mul(10, pow(x, 3))), x, { check: true, implicit: false, simplify: true, cubics: true }), 0)])).toBe('[-1]');
  });
});

